    12→
    13→/**
    14→ * Builds graph data structures from indexed files and their relationships.
    15→ *
    16→ * <p>Produces nodes and edges that can be rendered as Graphviz DOT, Mermaid,
    17→ * or exported for other visualization tools.
    18→ */
    19→public class GraphBuilder {
    20→
    21→    // Reference detection patterns
    22→    private static final Pattern JAVA_IMPORT = Pattern.compile("^import\\s+([\\w.]+);", Pattern.MULTILINE);
    23→    private static final Pattern MARKDOWN_LINK = Pattern.compile("\\[([^\\]]*)]\\(([^)]+)\\)", Pattern.MULTILINE);
    24→    private static final Pattern GENERIC_FILE_REF = Pattern.compile(
    25→            "(?:['\"`])([\\w./-]+\\.(?:java|py|js|ts|md|yaml|yml|json|xml|go|rs|kt))['\"`]");
    26→
    27→    /**
    28→     * A node in the file relationship graph.
    29→     */
    30→    public record GraphNode(
    31→            String id,
    32→            String label,
    33→            String fileType,
    34→            String language,
    35→            String repository,
    36→            long sizeBytes,
    37→            String directory
    38→    ) {}
    39→
    40→    /**
    41→     * An edge (relationship) between two nodes.
    42→     */
    43→    public record GraphEdge(
    44→            String sourceId,
    45→            String targetId,
    46→            String type,
    47→            int weight
    48→    ) {}
    49→
    50→    /**
    51→     * A complete graph with nodes and edges.
    52→     */
    53→    public record FileGraph(
    54→            List<GraphNode> nodes,
    55→            List<GraphEdge> edges,
    56→            String title
    57→    ) {
    58→        public Set<String> getDirectories() {
    59→            Set<String> dirs = new TreeSet<>();
    60→            for (GraphNode node : nodes) {
    61→                dirs.add(node.directory());
    62→            }
    63→            return dirs;
    64→        }
    65→    }
    66→
    67→    /**
    68→     * Builds a file relationship graph centered on a specific file.
    69→     *
    70→     * @param targetFile the focal file
    71→     * @param allFiles   all indexed files
    72→     * @param depth      how many levels of relationships to include
    73→     * @return the file graph
    74→     */
    75→    public FileGraph buildFileGraph(SearchResult targetFile, List<SearchResult> allFiles, int depth) {
    76→        Map<String, SearchResult> fileIndex = new LinkedHashMap<>();
    77→        Map<String, String> fileNameToPath = new HashMap<>();
    78→        for (SearchResult f : allFiles) {
    79→            fileIndex.put(f.relativePath(), f);
    80→            fileNameToPath.put(f.fileName(), f.relativePath());
    81→        }
    82→
    83→        // BFS from target file to discover relationships
    84→        Set<String> visitedFiles = new LinkedHashSet<>();
    85→        List<GraphEdge> edges = new ArrayList<>();
    86→
    87→        Queue<String> toVisit = new LinkedList<>();
    88→        toVisit.add(targetFile.relativePath());
    89→        visitedFiles.add(targetFile.relativePath());
    90→
    91→        int currentDepth = 0;
    92→        int currentLevelSize = 1;
    93→        int nextLevelSize = 0;
    94→
    95→        while (!toVisit.isEmpty() && currentDepth <= depth) {
    96→            String filePath = toVisit.poll();
    97→            currentLevelSize--;
    98→
    99→            SearchResult file = fileIndex.get(filePath);
   100→            if (file == null) continue;
   101→
   102→            // Find outgoing references
   103→            Set<String> refs = extractReferences(file, fileNameToPath);
   104→            for (String ref : refs) {
   105→                if (!ref.equals(filePath) && fileIndex.containsKey(ref)) {
   106→                    edges.add(new GraphEdge(filePath, ref, "references", 1));
   107→                    if (!visitedFiles.contains(ref) && currentDepth < depth) {
   108→                        visitedFiles.add(ref);
   109→                        toVisit.add(ref);
   110→                        nextLevelSize++;
   111→                    }
   112→                }
   113→            }
   114→
   115→            // Find incoming references
   116→            for (SearchResult other : allFiles) {
   117→                if (other.relativePath().equals(filePath)) continue;
   118→                Set<String> otherRefs = extractReferences(other, fileNameToPath);
   119→                if (otherRefs.contains(filePath)) {
   120→                    edges.add(new GraphEdge(other.relativePath(), filePath, "references", 1));
   121→                    if (!visitedFiles.contains(other.relativePath()) && currentDepth < depth) {
   122→                        visitedFiles.add(other.relativePath());
   123→                        toVisit.add(other.relativePath());
   124→                        nextLevelSize++;
   125→                    }
   126→                }
   127→            }
   128→
   129→            if (currentLevelSize == 0) {
   130→                currentDepth++;
   131→                currentLevelSize = nextLevelSize;
   132→                nextLevelSize = 0;
   133→            }
   134→        }
   135→
   136→        // Build nodes
   137→        List<GraphNode> nodes = new ArrayList<>();
   138→        for (String path : visitedFiles) {
   139→            SearchResult f = fileIndex.get(path);
   140→            if (f != null) {
   141→                String dir = path.contains("/") ? path.substring(0, path.lastIndexOf('/')) : ".";
   142→                nodes.add(new GraphNode(path, f.fileName(), f.fileType(), f.language(),
   143→                        f.repository(), f.sizeBytes(), dir));
   144→            }
   145→        }
   146→
   147→        // Deduplicate edges and compute weights
   148→        Map<String, GraphEdge> edgeMap = new LinkedHashMap<>();
   149→        for (GraphEdge edge : edges) {
   150→            String key = edge.sourceId() + "|" + edge.targetId();
   151→            edgeMap.merge(key, edge, (a, b) -> new GraphEdge(a.sourceId(), a.targetId(),
   152→                    a.type(), a.weight() + b.weight()));
   153→        }
   154→
   155→        return new FileGraph(nodes, new ArrayList<>(edgeMap.values()),
   156→                "File relationships: " + targetFile.relativePath());
   157→    }
   158→
   159→    /**
   160→     * Builds a module/directory-level graph.
   161→     */
   162→    public FileGraph buildModuleGraph(List<SearchResult> allFiles) {
   163→        // Group files by top-level directory
   164→        Map<String, List<SearchResult>> modules = new LinkedHashMap<>();
   165→        Map<String, String> fileNameToPath = new HashMap<>();
   166→
   167→        for (SearchResult f : allFiles) {
   168→            String[] parts = f.relativePath().split("/");
   169→            String module = parts.length > 1 ? parts[0] : ".";
   170→            modules.computeIfAbsent(module, k -> new ArrayList<>()).add(f);
   171→            fileNameToPath.put(f.fileName(), f.relativePath());
   172→        }
   173→
   174→        // Build module-level edges
   175→        Map<String, GraphEdge> edgeMap = new LinkedHashMap<>();
   176→        Map<String, Long> moduleSizes = new LinkedHashMap<>();
   177→
   178→        for (Map.Entry<String, List<SearchResult>> entry : modules.entrySet()) {
   179→            String sourceModule = entry.getKey();
   180→            long totalSize = 0;
   181→
   182→            for (SearchResult file : entry.getValue()) {
   183→                totalSize += file.sizeBytes();
   184→                Set<String> refs = extractReferences(file, fileNameToPath);
   185→                for (String ref : refs) {
   186→                    String[] parts = ref.split("/");
   187→                    String targetModule = parts.length > 1 ? parts[0] : ".";
   188→                    if (!targetModule.equals(sourceModule)) {
   189→                        String key = sourceModule + "|" + targetModule;
   190→                        edgeMap.merge(key,
   191→                                new GraphEdge(sourceModule, targetModule, "depends", 1),
   192→                                (a, b) -> new GraphEdge(a.sourceId(), a.targetId(),
   193→                                        a.type(), a.weight() + b.weight()));
   194→                    }
   195→                }
   196→            }
   197→            moduleSizes.put(sourceModule, totalSize);
   198→        }
   199→
   200→        // Create module nodes
   201→        List<GraphNode> nodes = new ArrayList<>();
   202→        for (Map.Entry<String, List<SearchResult>> entry : modules.entrySet()) {
   203→            nodes.add(new GraphNode(entry.getKey(),
   204→                    entry.getKey() + " (" + entry.getValue().size() + " files)",
   205→                    "MODULE", null, null,
   206→                    moduleSizes.getOrDefault(entry.getKey(), 0L),
   207→                    entry.getKey()));
   208→        }
   209→
   210→        return new FileGraph(nodes, new ArrayList<>(edgeMap.values()),
