     3→import io.exoreaction.synthesis.graph.GraphBuilder.*;
     4→
     5→import java.io.IOException;
     6→import java.nio.file.Files;
     7→import java.nio.file.Path;
     8→import java.util.*;
     9→
    10→/**
    11→ * Renders {@link FileGraph} data into various output formats:
    12→ * <ul>
    13→ *   <li>DOT (Graphviz format)</li>
    14→ *   <li>Mermaid markdown</li>
    15→ *   <li>PNG/SVG via Graphviz command-line tool</li>
    16→ * </ul>
    17→ *
    18→ * <p>Falls back to Mermaid output if Graphviz is not installed.
    19→ */
    20→public class GraphRenderer {
    21→
    22→    /** Output format enumeration. */
    23→    public enum Format {
    24→        PNG, SVG, MERMAID, DOT
    25→    }
    26→
    27→    /**
    28→     * Color scheme for different file types.
    29→     */
    30→    private static final Map<String, String> TYPE_COLORS = Map.of(
    31→            "CODE", "#4A90D9",       // blue
    32→            "MARKDOWN", "#5CB85C",   // green
    33→            "YAML", "#9B59B6",       // purple
    34→            "JSON", "#00BCD4",       // cyan
    35→            "CONFIG", "#F0AD4E",     // yellow/orange
    36→            "PDF", "#D9534F",        // red
    37→            "MODULE", "#2C3E50",     // dark blue-gray
    38→            "REPOSITORY", "#E74C3C"  // red
    39→    );
    40→
    41→    private static final String DEFAULT_COLOR = "#95A5A6";  // gray
    42→
    43→    /**
    44→     * Renders a graph to a file in the specified format.
    45→     *
    46→     * @param graph  the graph to render
    47→     * @param format output format
    48→     * @param output output file path
    49→     * @return true if rendering succeeded
    50→     */
    51→    public boolean render(FileGraph graph, Format format, Path output) throws IOException {
    52→        return switch (format) {
    53→            case DOT -> {
    54→                Files.writeString(output, toDot(graph));
    55→                yield true;
    56→            }
    57→            case MERMAID -> {
    58→                Files.writeString(output, toMermaid(graph));
    59→                yield true;
    60→            }
    61→            case PNG, SVG -> renderWithGraphviz(graph, format, output);
    62→        };
    63→    }
    64→
    65→    /**
    66→     * Converts a graph to Graphviz DOT format.
    67→     */
    68→    public String toDot(FileGraph graph) {
    69→        StringBuilder sb = new StringBuilder();
    70→        sb.append("digraph \"").append(escapeDot(graph.title())).append("\" {\n");
    71→        sb.append("    rankdir=LR;\n");
    72→        sb.append("    node [shape=box, style=\"filled,rounded\", fontname=\"Helvetica\", fontsize=10];\n");
    73→        sb.append("    edge [fontname=\"Helvetica\", fontsize=8];\n");
    74→        sb.append("    graph [fontname=\"Helvetica\", label=\"").append(escapeDot(graph.title()))
    75→                .append("\", labelloc=t, fontsize=14];\n");
    76→        sb.append("    bgcolor=\"transparent\";\n\n");
    77→
    78→        // Group nodes by directory (subgraph clusters)
    79→        Map<String, List<GraphNode>> byDir = new LinkedHashMap<>();
    80→        for (GraphNode node : graph.nodes()) {
    81→            byDir.computeIfAbsent(node.directory(), k -> new ArrayList<>()).add(node);
    82→        }
    83→
    84→        int clusterIdx = 0;
    85→        for (Map.Entry<String, List<GraphNode>> entry : byDir.entrySet()) {
    86→            if (byDir.size() > 1) {
    87→                sb.append("    subgraph cluster_").append(clusterIdx++).append(" {\n");
    88→                sb.append("        label=\"").append(escapeDot(entry.getKey())).append("\";\n");
    89→                sb.append("        style=dashed;\n");
    90→                sb.append("        color=\"#BDC3C7\";\n");
    91→            }
    92→
    93→            for (GraphNode node : entry.getValue()) {
    94→                String color = TYPE_COLORS.getOrDefault(node.fileType(), DEFAULT_COLOR);
    95→                String fontColor = isDarkColor(color) ? "white" : "#2C3E50";
    96→                sb.append("        \"").append(escapeDot(node.id())).append("\" [")
    97→                        .append("label=\"").append(escapeDot(node.label())).append("\", ")
    98→                        .append("fillcolor=\"").append(color).append("\", ")
    99→                        .append("fontcolor=\"").append(fontColor).append("\"")
   100→                        .append("];\n");
   101→            }
   102→
   103→            if (byDir.size() > 1) {
   104→                sb.append("    }\n\n");
   105→            }
   106→        }
   107→
   108→        // Edges
   109→        for (GraphEdge edge : graph.edges()) {
   110→            String style = edge.type().equals("circular") ? "color=red, style=bold" : "color=\"#7F8C8D\"";
   111→            String penwidth = edge.weight() > 1 ? ", penwidth=" + Math.min(edge.weight(), 5) : "";
   112→            sb.append("    \"").append(escapeDot(edge.sourceId())).append("\" -> \"")
   113→                    .append(escapeDot(edge.targetId())).append("\" [")
   114→                    .append(style).append(penwidth).append("];\n");
   115→        }
   116→
   117→        sb.append("}\n");
   118→        return sb.toString();
   119→    }
   120→
   121→    /**
   122→     * Converts a graph to Mermaid diagram format.
   123→     */
   124→    public String toMermaid(FileGraph graph) {
   125→        StringBuilder sb = new StringBuilder();
   126→        sb.append("```mermaid\ngraph LR\n");
   127→
   128→        // Nodes
   129→        for (GraphNode node : graph.nodes()) {
   130→            String id = sanitizeId(node.id());
   131→            sb.append("    ").append(id).append("[\"").append(node.label()).append("\"]\n");
   132→
   133→            // Style based on type
   134→            String color = TYPE_COLORS.getOrDefault(node.fileType(), DEFAULT_COLOR);
   135→            sb.append("    style ").append(id).append(" fill:").append(color)
   136→                    .append(",stroke:#333,stroke-width:1px,color:white\n");
   137→        }
   138→
   139→        sb.append("\n");
   140→
   141→        // Edges
   142→        for (GraphEdge edge : graph.edges()) {
   143→            String sourceId = sanitizeId(edge.sourceId());
   144→            String targetId = sanitizeId(edge.targetId());
   145→            if (edge.weight() > 1) {
   146→                sb.append("    ").append(sourceId).append(" ==>|").append(edge.weight())
   147→                        .append("| ").append(targetId).append("\n");
   148→            } else {
   149→                sb.append("    ").append(sourceId).append(" --> ").append(targetId).append("\n");
   150→            }
   151→        }
   152→
   153→        sb.append("```\n");
   154→        return sb.toString();
   155→    }
   156→
   157→    /**
   158→     * Renders the graph to PNG or SVG using the Graphviz `dot` command.
   159→     * Falls back to Mermaid if Graphviz is not installed.
   160→     *
   161→     * @return true if Graphviz rendered successfully, false if fell back to Mermaid
   162→     */
   163→    private boolean renderWithGraphviz(FileGraph graph, Format format, Path output) throws IOException {
   164→        if (!isGraphvizAvailable()) {
   165→            // Fallback to Mermaid markdown
   166→            Path mermaidOutput = output.resolveSibling(
   167→                    output.getFileName().toString().replaceAll("\\.(png|svg)$", ".md"));
   168→            Files.writeString(mermaidOutput, toMermaid(graph));
   169→            return false; // Signal that we fell back
   170→        }
   171→
   172→        // Write DOT to temp file
   173→        Path dotFile = Files.createTempFile("synthesis-graph-", ".dot");
   174→        try {
   175→            Files.writeString(dotFile, toDot(graph));
   176→
   177→            String formatFlag = format == Format.PNG ? "png" : "svg";
   178→            ProcessBuilder pb = new ProcessBuilder(
   179→                    "dot", "-T" + formatFlag, dotFile.toString(), "-o", output.toString()
   180→            );
   181→            pb.redirectErrorStream(true);
   182→            Process process = pb.start();
   183→            int exitCode = process.waitFor();
   184→
   185→            return exitCode == 0;
   186→        } catch (InterruptedException e) {
   187→            Thread.currentThread().interrupt();
   188→            return false;
   189→        } finally {
   190→            Files.deleteIfExists(dotFile);
   191→        }
   192→    }
