   260→            char c = json.charAt(i);
   261→            if (c == '"' && (i == 0 || json.charAt(i - 1) != '\\')) {
   262→                inString = !inString;
   263→            } else if (!inString) {
   264→                if (c == '[') depth++;
   265→                else if (c == ']') {
